sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

	//fetching task ID and short desc of the previous task which got cancelled
    var previousTaskId = current.number;
    var previousShortDesc = current.short_description;

	//properties used
    var mssMocsShortDesc = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.short.description.mocs");
    var mssMocsAssign = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.assignment.group.mocs");
    var mssMocsDesc = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.description.mocs");
    var mssMocsThresholdSdesc = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.short.description.mocs.threshold");
    var mssMocsThresholdDesc = gs.getProperty("x_hsb11_hsbc_mss_t.hsbc.description.mocs.threshold");

    if (current.case_task_type == "QTRACK") {

        var qtrackOutbound = new GlideRecord("x_hsb11_hsbcmss_qw_hsbc_qtrack_email_outbound");
        qtrackOutbound.addQuery("servicenow_task_id.number", current.number);
        qtrackOutbound.query();
        if (qtrackOutbound.next()) {
            var qtrackErrorBody = qtrackOutbound.error_body;

			//creating new task for mocs when widget failure
            var qtrackTaskMocs = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
            qtrackTaskMocs.initialize();
            qtrackTaskMocs.parent = current.parent;
            qtrackTaskMocs.setValue("assignment_group", mssMocsAssign);
            qtrackTaskMocs.short_description = previousTaskId + " for " + previousShortDesc + " " + mssMocsShortDesc;
            qtrackTaskMocs.description = mssMocsDesc + '.\n' + qtrackErrorBody.toString();
            qtrackTaskMocs.insert();
        }

    } else if (current.case_task_type == "SYMPHONY" || current.case_task_type == "SYMPHONY_CHASER" || current.case_task_type == "SYMPHONY_RECALL") {

        var symphonyOutbound = new GlideRecord("x_hsb11_mss_sw_hsbc_outbound_symphony_message_log");
        symphonyOutbound.addQuery("servicenow_task_id.number", current.number);
        symphonyOutbound.query();
        if (symphonyOutbound.next()) {
            var symphonyErrorBody = symphonyOutbound.error_body;

            if (symphonyOutbound.response_code != '418') {
                var symphonyTaskMocs = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
                symphonyTaskMocs.initialize();
                symphonyTaskMocs.parent = current.parent;
                symphonyTaskMocs.setValue("assignment_group", mssMocsAssign);
                symphonyTaskMocs.short_description = previousTaskId + " for " + previousShortDesc + " " + mssMocsShortDesc;
                symphonyTaskMocs.description = mssMocsDesc + '.\n' + symphonyErrorBody.toString();
                symphonyTaskMocs.insert();
            }else if(symphonyOutbound.response_code == '418'){
            var symphonyTaskMocsThreshold = new GlideRecord("x_hsb11_hsbc_mss_t_trade_task");
            symphonyTaskMocsThreshold.initialize();
            symphonyTaskMocsThreshold.parent = current.parent;
            symphonyTaskMocsThreshold.setValue("assignment_group", mssMocsAssign);
            symphonyTaskMocsThreshold.setValue("short_description", mssMocsThresholdSdesc);
            symphonyTaskMocsThreshold.setValue("description", mssMocsThresholdDesc);
            //symphonyTaskMocsThreshold.description = mssMocsDesc + '.\n' + symphonyErrorBody.toString();
            symphonyTaskMocsThreshold.insert();

        } 
        }
	}

})(current, previous);
